import sys

MOD = 10**9 + 7

def solve(n, m, s):
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(m):
        ndp = [[0] * (n + 1) for _ in range(i + 2)]
        for open in range(i + 1):
            for close in range(open + 1):
                if s[i] == '(':
                    if open + 1 <= n:
                        ndp[open + 1][close] = (ndp[open + 1][close] + dp[open][close]) % MOD
                else:
                    if close + 1 <= open:
                        ndp[open][close + 1] = (ndp[open][close + 1] + dp[open][close]) % MOD
        dp = ndp

    result = 0
    for open in range(m + 1):
        for close in range(open + 1):
            if open + (n - m) // 2 == close + (n - m) // 2 and (n - m) % 2 == 0:
                result = (result + dp[open][close]) % MOD

    return result

def main():
    import sys
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    m = int(input[1])
    s = input[2]
    print(solve(n, m, s))

main()
